DATA = [
(1,2,'انواع بازارها و ابزارهای معاملاتی','بازار سهام برای مالکیت بخشی از شرکت، بازار اوراق بدهی برای تأمین مالی، بازار ارز برای مبادله ارزها و بازار کالا برای معامله دارایی‌هایی مانند طلا و نفت شکل گرفته‌اند. ساختار معاملات، ساعات فعالیت، تسویه و نهاد ناظر در هر بازار متفاوت است.','سهام یک شرکت، جفت‌ارز EUR/USD و قرارداد آتی طلا را از نظر دارایی پایه، ساعات معامله و ریسک اهرم کنار هم بگذار.','فرض اینکه خرید CFD همان مالکیت دارایی پایه است.','برای سه ابزار، نوع قرارداد، هزینه معامله و خطر اصلی را در یک جدول شخصی بنویس.'),
(1,3,'انتخاب بازار مناسب برای معامله‌گری','انتخاب بازار باید با سرمایه، ساعات آزاد، دسترسی قانونی، نقدشوندگی، هزینه اجرا و تحمل ریسک هماهنگ باشد. بازار پرنوسان لزوماً مناسب‌تر نیست؛ کیفیت داده و امکان تمرین در حساب آزمایشی نیز مهم است.','فردی که فقط عصرها فرصت دارد باید ساعت فعال بازار، اسپرد آن ساعت و محدودیت‌های کارگزار را بررسی کند.','انتخاب بازار فقط بر اساس سودهای منتشرشده در شبکه‌های اجتماعی.','دو بازار را با پنج معیار هزینه، ساعت، نقدشوندگی، ریسک و امکان بک‌تست امتیازدهی کن.'),
(2,1,'پیپ، لات و حجم معاملات','پیپ واحد رایج بیان تغییر قیمت در بسیاری از جفت‌ارزهاست؛ اندازه آن با نماد متفاوت است. لات اندازه قراردادی موقعیت را نشان می‌دهد و ارزش پولی هر حرکت قیمت به مشخصات نماد، حجم و ارز حساب بستگی دارد.','در EUR/USD حرکت 1.0800 تا 1.0810 معمولاً ده پیپ است؛ ارزش دلاری آن بدون دانستن حجم معامله تعیین نمی‌شود.','استفاده از ارزش ثابت پیپ برای تمام نمادها، به‌خصوص طلا و شاخص‌ها.','در مشخصات سه نماد، contract size و tick size را پیدا و تفاوتشان را یادداشت کن.'),
(2,2,'اسپرد، کمیسیون و اهرم معاملاتی','اسپرد فاصله قیمت خرید و فروش است؛ کمیسیون ممکن است جداگانه محاسبه شود. اهرم امکان کنترل ارزش اسمی بزرگ‌تر با وجه تضمین کمتر را می‌دهد، اما زیان را نسبت به سرمایه نیز تشدید می‌کند. هزینه سواپ یا تأمین مالی را هم باید بررسی کرد.','اگر اسپرد معادل ۲ دلار و کمیسیون رفت‌وبرگشت ۳ دلار باشد، معامله پیش از تغییر قیمت ۵ دلار هزینه دارد.','اشتباه گرفتن مارجین پایین با ریسک پایین.','برای یک معامله فرضی هزینه کل ورود، خروج و نگهداری شبانه را از جدول کارگزار استخراج کن.'),
(2,3,'سفارش‌گذاری و مدیریت معاملات','سفارش بازار اولویت اجرا دارد اما ممکن است با لغزش همراه باشد؛ سفارش محدود قیمت را کنترل می‌کند ولی تضمین اجرا ندارد. سفارش توقف برای فعال‌شدن پس از رسیدن قیمت به سطح مشخص استفاده می‌شود. حد ضرر هم در جهش‌های شدید الزاماً دقیقاً در قیمت تعیین‌شده اجرا نمی‌شود.','برای خرید فرضی در ۱۰۰، حد ضرر ۹۷ و هدف ۱۰۶، ریسک اسمی ۳ و بازده هدف ۶ واحد است؛ نسبت پاداش به ریسک ۲ است.','قرار دادن سفارش بدون بررسی حجم، جهت، نوع سفارش و اعتبار زمانی.','قبل از تأیید یک سفارش آزمایشی، چهار مورد نماد، حجم، حد ضرر و هزینه را بررسی کن.'),
(3,1,'ساختار نمودار و تایم‌فریم','نمودار خطی معمولاً قیمت‌های انتخاب‌شده مانند بسته‌شدن را متصل می‌کند؛ نمودار شمعی باز، بسته، بیشینه و کمینه هر بازه را نشان می‌دهد. تایم‌فریم کوتاه‌تر جزئیات و نویز بیشتری دارد و تایم‌فریم بالاتر برای درک زمینه مناسب‌تر است.','یک حرکت در نمودار پنج‌دقیقه‌ای ممکن است در نمودار یک‌ساعته فقط بخشی از یک کندل باشد.','نتیجه‌گیری درباره روند بلندمدت از دو کندل کوتاه‌مدت.','یک نماد را در سه تایم‌فریم باز کن و تفاوت روند قابل مشاهده را ثبت کن.'),
(3,2,'کندل‌شناسی مقدماتی','هر کندل چهار قیمت بازشدن، بیشینه، کمینه و بسته‌شدن دارد. بدنه فاصله باز و بسته و سایه‌ها محدوده حرکت را نشان می‌دهند. شکل کندل بدون موقعیت آن در ساختار بازار و حجم معاملات، سیگنال مستقل قابل اتکا نیست.','کندل با سایه پایینی بلند نزدیک حمایت ممکن است رد قیمت پایین را نشان دهد، ولی برای نتیجه‌گیری به کندل‌های بعدی و شرایط بازار نیاز است.','تعبیر قطعی یک کندل دوجی به‌عنوان برگشت روند.','سه کندل را انتخاب کن و OHLC و محل آن‌ها نسبت به حمایت و مقاومت را بنویس.'),
(3,3,'حمایت و مقاومت مقدماتی','حمایت و مقاومت نواحی‌ای هستند که در گذشته واکنش عرضه و تقاضا در آن‌ها دیده شده است؛ معمولاً بهتر است آن‌ها را محدوده در نظر بگیریم نه خط دقیق. تعداد برخوردها، واکنش‌ها و شرایط شکست بر اعتبار عملی ناحیه اثر می‌گذارند.','اگر قیمت چند بار در بازه ۹۸ تا ۱۰۰ واکنش نشان داده، ناحیه حمایت احتمالی را به‌صورت باند رسم کن.','رسم ده‌ها خط روی نمودار و انتظار واکنش قطعی از هر خط.','دو ناحیه را روی نمودار مشخص و دلیل انتخابشان را در یک جمله توضیح بده.'),
(4,1,'ریسک و بازده در معامله‌گری','ریسک مقدار زیانی است که در سناریوی نامطلوب ممکن است رخ دهد؛ بازده بالقوه باید همراه احتمال موفقیت، هزینه اجرا و افت سرمایه بررسی شود. امید ریاضی ترکیبی از میانگین سود، میانگین زیان و فراوانی هرکدام است.','سیستمی با ۴۰٪ برد، میانگین سود ۲R و میانگین زیان ۱R پیش از هزینه‌ها امید ریاضی ۰٫۲R دارد.','قضاوت درباره استراتژی فقط با درصد معاملات برنده.','برای ۲۰ معامله آزمایشی، میانگین برد و باخت و امید ریاضی را محاسبه کن.'),
(4,2,'حد ضرر و حد سود','حد ضرر باید در نقطه‌ای قرار گیرد که فرضیه معامله بی‌اعتبار می‌شود، نه صرفاً فاصله‌ای دلخواه. حد سود نیز می‌تواند بر اساس ساختار قیمت و نسبت بازده به ریسک تعیین شود. گپ و لغزش ممکن است زیان واقعی را از مقدار برنامه‌ریزی‌شده بیشتر کند.','اگر ورود ۲۰۰، حد ضرر ۱۹۶ و هدف ۲۰۸ باشد، فاصله ریسک ۴ و هدف ۸ واحد است.','دور کردن حد ضرر پس از حرکت قیمت خلاف معامله برای فرار از پذیرش زیان.','برای یک نمودار، محل بی‌اعتبار شدن تحلیل را قبل از تعیین حجم مشخص کن.'),
(4,3,'محاسبه حجم معامله','ابتدا سقف زیان مجاز را از سرمایه و درصد ریسک محاسبه کن؛ سپس آن را بر زیان هر واحد حجم تا حد ضرر، با لحاظ هزینه و مشخصات قرارداد، تقسیم کن. حجم نهایی باید به گام مجاز کارگزار گرد شود.','برای سرمایه ۱۰۰۰ دلار و ریسک ۱٪، بودجه زیان برنامه‌ریزی‌شده ۱۰ دلار است؛ حجم به فاصله حد ضرر و ارزش هر واحد حرکت بستگی دارد.','انتخاب لات ثابت بدون توجه به فاصله حد ضرر.','در حساب آزمایشی حجم سه معامله با فاصله‌های حد ضرر متفاوت را محاسبه و مقایسه کن.'),
(5,1,'ساختار بازار و روندها','در تعریف ساده، روند صعودی با سقف‌ها و کف‌های بالاتر و روند نزولی با سقف‌ها و کف‌های پایین‌تر توصیف می‌شود. بازار می‌تواند وارد محدوده خنثی شود؛ تشخیص ساختار به تایم‌فریم و روش تعیین نقاط نوسانی وابسته است.','روی یک نمودار، دو سقف و دو کف متوالی را علامت بزن و بررسی کن آیا ترتیب آن‌ها با روند موردنظر سازگار است.','تحمیل برچسب روند به بازاری که ساختار واضح ندارد.','سه نمونه روند صعودی، نزولی و خنثی را ثبت کن.'),
(5,2,'سقف‌ها و کف‌های قیمتی','سقف و کف نوسانی نقاط برگشت نسبی‌اند و با انتخاب تعداد کندل‌های اطراف یا معیار نوسان تعریف می‌شوند. نقاط مهم ساختاری باید از نوسان‌های خرد تفکیک شوند. تغییر تعریف نقطه نوسانی می‌تواند نتیجه تحلیل را عوض کند.','یک سقف محلی پنج‌کندلی ممکن است در تایم‌فریم بالاتر اصلاً سقف ساختاری مهمی نباشد.','تغییر دلخواه تعریف سقف و کف بعد از دیدن نتیجه معامله.','یک قاعده ثابت برای تعیین سقف و کف انتخاب و روی ۳۰ کندل آزمایش کن.'),
(5,3,'شکست ساختار بازار','شکست ساختار زمانی مطرح می‌شود که قیمت از یک سقف یا کف مهم عبور کند؛ اما عبور لحظه‌ای، بسته‌شدن کندل و تداوم حرکت معانی متفاوتی دارند. شکست می‌تواند ادامه روند یا نشانه تغییر احتمالی باشد و باید در زمینه ساختاری بررسی شود.','قیمت بالای سقف قبلی می‌رود ولی کندل زیر آن بسته می‌شود؛ این رفتار با شکست تثبیت‌شده یکسان نیست.','ورود فوری به هر عبور کوتاه از سقف یا کف.','سه شکست را با معیار ثابت بسته‌شدن کندل ارزیابی کن.'),
(5,4,'تشخیص نواحی مهم قیمت','نواحی مهم را می‌توان از تراکم معاملات، واکنش‌های پیشین، سقف و کف ساختاری یا محدوده‌های عرضه و تقاضا استخراج کرد. ناحیه باید قابل توضیح، محدود و قابل آزمون باشد؛ تراکم بیش از حد نواحی تصمیم‌گیری را دشوار می‌کند.','محدوده‌ای که قبلاً شروع یک حرکت سریع بوده ممکن است برای بررسی واکنش بعدی ارزشمند باشد، نه اینکه بازگشت را تضمین کند.','گسترش ناحیه بعد از وقوع حرکت برای درست نشان دادن تحلیل.','حداکثر سه ناحیه مهم یک نمودار را با دلیل انتخاب مشخص کن.'),
(6,1,'روند و خطوط روند','خط روند ابزار بصری اتصال کف‌های صعودی یا سقف‌های نزولی است. اعتبار آن به روش رسم، تعداد تماس و شرایط شکست وابسته است. خط روند به‌تنهایی علت حرکت قیمت نیست و نباید جایگزین مدیریت ریسک شود.','اگر دو کف بالارونده خطی بسازند، برخورد سوم می‌تواند ناحیه مشاهده واکنش باشد، نه دستور خرید قطعی.','تغییر زاویه خط برای عبور دادن آن از هر نقطه دلخواه.','دو روش رسم خط روند را روی یک نمودار مقایسه و قواعد ثابت انتخاب کن.'),
(6,2,'سطوح حمایت و مقاومت پیشرفته','در بررسی پیشرفته، قدرت واکنش، تعداد دفعات آزمون، مدت سپری‌شده، شکست و بازآزمایی و شرایط نوسان اهمیت دارند. حمایت شکسته‌شده گاهی به مقاومت تبدیل می‌شود، اما این الگو قطعی نیست.','پس از عبور و تثبیت زیر یک محدوده حمایت، بازگشت قیمت به همان محدوده را بدون پیش‌فرض قطعی مشاهده کن.','فرض اینکه هر سطح قدیمی تا ابد معتبر می‌ماند.','پنج ناحیه تاریخی را از نظر تازگی و تعداد واکنش درجه‌بندی کن.'),
(6,3,'الگوهای قیمتی کاربردی','الگوهایی مانند مثلث، پرچم و سر و شانه خلاصه‌ای بصری از رفتار قیمت‌اند. تعریف دقیق نقاط، شکست، حد ضرر و هدف باید قبل از آزمون مشخص باشد. عملکرد الگوها به بازار، تایم‌فریم و هزینه اجرا وابسته است.','برای یک مثلث، خط‌های همگرا، نقطه شکست احتمالی و سناریوی شکست ناموفق را از پیش بنویس.','دیدن الگو فقط پس از مشخص شدن نتیجه قیمت.','ده نمونه از یک الگو را با معیارهای یکسان برچسب‌گذاری کن.'),
(6,4,'تحلیل چند تایم‌فریمی','تحلیل چند تایم‌فریمی برای تفکیک زمینه کلان، ناحیه تصمیم و زمان‌بندی اجرا استفاده می‌شود. تایم‌فریم بالاتر الزاماً همیشه درست نیست؛ تضاد میان بازه‌ها باید به‌عنوان عدم‌قطعیت ثبت شود.','روند چهارساعته صعودی است ولی پنج‌دقیقه‌ای نزولی؛ این ممکن است اصلاح کوتاه‌مدت باشد یا شروع تغییر بزرگ‌تر.','انتخاب تایم‌فریم دلخواه فقط برای تأیید نظر اولیه.','قبل از معامله، جهت، ناحیه و ماشه ورود را در سه تایم‌فریم جدا ثبت کن.'),
(7,1,'مفهوم نقدینگی در بازار','نقدینگی به امکان معامله با اثر قیمتی محدود مربوط است و با حجم، عمق دفتر سفارش و اسپرد سنجیده می‌شود. در ادبیات پرایس اکشن، اصطلاح «نواحی نقدینگی» گاهی به نقاط تجمع سفارش‌های توقف اشاره دارد؛ این ادعا معمولاً از نمودار قیمت به‌تنهایی قابل اثبات نیست.','نزدیک سقف واضح ممکن است سفارش‌های توقف وجود داشته باشند، ولی بدون داده سفارش نمی‌توان مقدار آن‌ها را قطعی دانست.','یکی دانستن حدس درباره توقف‌ها با مشاهده واقعی دفتر سفارش.','تفاوت نقدینگی قابل مشاهده و نقدینگی استنباط‌شده را با دو مثال توضیح بده.'),
(7,2,'شکار نقدینگی و شکست‌های کاذب','شکست کاذب زمانی رخ می‌دهد که قیمت از سطح عبور کند ولی ادامه حرکت تثبیت نشود. اصطلاح شکار نقدینگی تفسیر احتمالی این رفتار است، نه اثبات قصد بازیگران بازار. تأیید، محل بی‌اعتباری و هزینه اجرا باید تعریف شوند.','قیمت بالای سقف روز قبل می‌رود، سپس زیر آن بسته می‌شود؛ این یک نمونه قابل بررسی از شکست ناموفق است.','نسبت دادن هر شکست کاذب به دستکاری عمدی بازار.','پنج عبور ناموفق از سطوح را با زمان و واکنش بعدی ثبت کن.'),
(7,3,'ناحیه‌های عرضه و تقاضا','ناحیه عرضه یا تقاضا محدوده‌ای است که پیش از یک حرکت مشخص قیمت قرار داشته و احتمال واکنش بعدی در آن بررسی می‌شود. تعریف پهنا، تازگی، دفعات لمس و شرایط ابطال باید ثابت باشد. هیچ ناحیه‌ای سفارش پنهان را به‌طور قطعی نشان نمی‌دهد.','محدوده کوچک پیش از جهش قیمت را مشخص کن و در بازگشت بعدی، واکنش واقعی را بدون جابه‌جایی مرزها ثبت کن.','رسم ناحیه پس از دیدن واکنش و ادعای پیش‌بینی قبلی.','برای سه ناحیه، مرز بالا و پایین و معیار ابطال تعیین کن.'),
(7,4,'تأیید ورود بر اساس رفتار قیمت','تأیید ورود می‌تواند شامل بسته‌شدن کندل، تغییر ساختار خرد، واکنش از ناحیه و کنترل اسپرد باشد. افزودن تأییدها معمولاً تعداد فرصت‌ها را کاهش می‌دهد؛ باید تأثیر آن‌ها با بک‌تست سنجیده شود.','پس از لمس حمایت، منتظر بسته‌شدن کندل بالای سقف خرد می‌مانی؛ این تأخیر ممکن است کیفیت یا قیمت ورود را تغییر دهد.','افزودن فیلترهای متعدد بدون بررسی کاهش نمونه معاملات.','دو قاعده ورود را روی یک مجموعه داده یکسان مقایسه کن.'),
(8,1,'شاخص‌های اقتصادی مهم','تورم، اشتغال، رشد اقتصادی و شاخص‌های فعالیت کسب‌وکار از داده‌های اثرگذار بر انتظارات بازارند. اثر هر گزارش به اختلاف مقدار واقعی با انتظار، بازنگری داده‌ها و شرایط اقتصاد بستگی دارد.','تورم بالاتر از انتظار ممکن است انتظارات نرخ بهره را تغییر دهد، اما واکنش ارز یا طلا همیشه یک‌جهته نیست.','معامله صرفاً بر اساس مثبت یا منفی بودن عدد خبر.','برای سه خبر اقتصادی، مقدار پیش‌بینی، واقعی و بازنگری‌شده را کنار هم ثبت کن.'),
(8,2,'نرخ بهره و سیاست پولی','بانک مرکزی با ابزارهایی مانند نرخ سیاستی و عملیات بازار باز بر شرایط مالی اثر می‌گذارد. بازارها معمولاً به مسیر مورد انتظار نرخ‌ها واکنش نشان می‌دهند، نه فقط تصمیم همان روز. تفاوت نرخ بهره اسمی و واقعی برای تحلیل دارایی‌ها مهم است.','ثابت ماندن نرخ بهره می‌تواند همراه با رشد ارز باشد اگر پیام بانک مرکزی سخت‌گیرانه‌تر از انتظار باشد.','فرض اینکه افزایش نرخ بهره همیشه و فوراً ارزش یک ارز را بالا می‌برد.','در یک بیانیه بانک مرکزی، تصمیم فعلی و راهنمایی آینده را جدا کن.'),
(8,3,'تأثیر اخبار بر طلا و ارز','طلا و ارز به ترکیبی از نرخ بهره واقعی، دلار، ریسک‌گریزی و جریان سرمایه واکنش نشان می‌دهند. هنگام انتشار خبر، اسپرد و لغزش می‌تواند شدید شود؛ جهت اولیه قیمت نیز ممکن است سریعاً معکوس شود.','پس از گزارش اشتغال آمریکا، هم بازده اوراق و هم دلار را بررسی کن و حرکت طلا را در کنار آن‌ها ببین.','تعیین معامله قطعی فقط با دانستن عنوان خبر.','سه رویداد خبری را از نظر نوسان، اسپرد و حرکت ۱۵ دقیقه اول مقایسه کن.'),
(8,4,'ترکیب تحلیل بنیادی و تکنیکال','تحلیل بنیادی برای ساخت سناریو و تشخیص محرک‌ها و تحلیل تکنیکال برای تعریف ناحیه، زمان‌بندی و ابطال سناریو استفاده می‌شود. تضاد میان دو تحلیل باید به تصمیم روشن مانند کاهش ریسک یا عدم معامله منجر شود.','انتظار افزایش نوسان پس از تصمیم نرخ بهره داری؛ با نمودار محدوده‌های کلیدی و نقطه ابطال را مشخص می‌کنی.','تبدیل دیدگاه بنیادی بلندمدت به توجیه نگهداری معامله زیان‌ده کوتاه‌مدت.','برای یک رویداد، سناریوی صعودی، نزولی و شرط عدم معامله بنویس.'),
(9,1,'اجزای یک استراتژی معاملاتی','استراتژی قابل آزمون باید بازار، تایم‌فریم، شرایط ورود، خروج، اندازه موقعیت، هزینه‌ها و محدودیت زمانی را مشخص کند. هر قانون مبهم، تکرارپذیری و اعتبار بک‌تست را کاهش می‌دهد.','عبارت «وقتی بازار قوی بود بخر» مبهم است؛ باید قدرت را با معیار قابل اندازه‌گیری تعریف کرد.','تغییر قوانین در میانه بک‌تست برای بهتر شدن نتیجه.','استراتژی فرضی خود را در قالب پنج قانون بدون عبارت مبهم بنویس.'),
(9,2,'قوانین ورود و خروج','قانون ورود باید شرایط لازم و زمان فعال‌شدن سفارش را مشخص کند؛ خروج می‌تواند با حد ضرر، حد سود، زمان یا تغییر شرایط انجام شود. خروج‌های چندگانه باید اولویت و رفتار هم‌زمان مشخص داشته باشند.','اگر در یک کندل هم حد سود و هم حد ضرر لمس شده باشند، بک‌تست بدون داده دقیق‌تر نمی‌تواند ترتیب واقعی را قطعی بداند.','نادیده گرفتن ابهام اجرای درون کندل.','برای یک معامله فرضی، ترتیب اجرای قوانین خروج را مکتوب کن.'),
(9,3,'طراحی چک‌لیست معاملاتی','چک‌لیست کوتاه و قابل اجرا از خطاهای تکراری پیشگیری می‌کند. موارد مهم شامل وضعیت بازار، وجود سیگنال معتبر، حد ضرر، حجم، هزینه، رویداد خبری و وضعیت روانی است. چک‌لیست باید قبل از ثبت سفارش تکمیل شود.','اگر اسپرد از حد مجاز استراتژی بیشتر باشد، حتی با وجود سیگنال، تصمیم «عدم ورود» ثبت می‌شود.','چک‌لیستی طولانی که در عمل استفاده نمی‌شود.','یک چک‌لیست هفت‌موردی بساز و در ده معامله آزمایشی اجرا کن.'),
(10,1,'اصول بک‌تست معتبر','بک‌تست باید داده باکیفیت، قوانین ثابت، هزینه واقعی، زمان‌بندی صحیح و جلوگیری از نگاه به آینده داشته باشد. داده‌های تعدیل‌نشده یا ناقص و اجرای غیرواقعی می‌توانند سود را بیش‌برآورد کنند.','اگر سیگنال از قیمت بسته‌شدن کندل ساخته می‌شود، ورود در همان قیمت بسته‌شدن بدون فرض اجرایی معتبر ممکن است خوش‌بینانه باشد.','استفاده ناخواسته از اطلاعاتی که در لحظه معامله در دسترس نبوده‌اند.','فهرست منابع داده، فرض‌های هزینه و مدل اجرای بک‌تست را مستند کن.'),
(10,2,'شاخص‌های ارزیابی استراتژی','سود خالص، افت سرمایه، ضریب سود، امید ریاضی، تعداد معاملات و ثبات عملکرد مکمل یکدیگرند. سود بالا با نمونه کوچک یا افت سرمایه شدید لزوماً نشانه کیفیت نیست. باید توزیع بازده و ریسک دنباله‌ای نیز بررسی شود.','دو سیستم با سود ۲۰۰ دلار ممکن است افت سرمایه ۵٪ و ۴۰٪ داشته باشند؛ ارزیابی آن‌ها یکسان نیست.','انتخاب سیستم فقط بر اساس بیشترین سود خالص.','برای دو گزارش بک‌تست، پنج شاخص ریسک و عملکرد را در جدول مقایسه کن.'),
(10,3,'بیش‌برازش و خطاهای بک‌تست','بیش‌برازش زمانی رخ می‌دهد که پارامترها بیش از حد با نویز داده گذشته هماهنگ شوند. آزمون مکرر تنظیمات، انتخاب بهترین نتیجه و نادیده گرفتن هزینه‌ها خطر بیش‌برازش را افزایش می‌دهد.','اگر از میان هزار ترکیب پارامتر بهترین را انتخاب کنی، نتیجه روی همان داده احتمالاً خوش‌بینانه است.','تلقی سود تاریخی به‌عنوان تضمین عملکرد آینده.','یک پارامتر را در بازه‌ای منطقی تغییر بده و پایداری نتایج را بررسی کن.'),
(10,4,'آزمون خارج از نمونه','در آزمون خارج از نمونه، بخشی از داده که در طراحی و تنظیم استراتژی استفاده نشده برای ارزیابی نهایی کنار گذاشته می‌شود. آزمون راه‌رونده و تفکیک زمانی می‌توانند به بررسی پایداری کمک کنند.','قوانین را روی داده سال اول تنظیم کن و بدون تغییر روی سال دوم آزمایش کن؛ سپس تفاوت شاخص‌ها را ثبت کن.','تنظیم مجدد پارامترها پس از مشاهده نتایج خارج از نمونه و همچنان نامیدن آن داده به‌عنوان آزمون مستقل.','یک تقسیم زمانی توسعه، اعتبارسنجی و آزمون نهایی تعریف کن.'),
(11,1,'کنترل هیجان و تصمیم‌گیری','ترس از جا ماندن، انتقام‌گیری و اعتمادبه‌نفس بیش از حد می‌توانند اجرای برنامه را مختل کنند. راهکار عملی شامل قوانین پیشینی، وقفه پس از رویدادهای پرتنش و ثبت دلایل تصمیم است.','پس از دو ضرر، به‌جای افزایش حجم برای جبران، طبق قانون از پیش تعیین‌شده وضعیت خود را ارزیابی می‌کنی.','تصمیم‌گیری درباره حجم معامله در اوج هیجان.','برای سه محرک هیجانی خود، یک پاسخ رفتاری مشخص بنویس.'),
(11,2,'انضباط و پایبندی به برنامه','انضباط یعنی اجرای قواعد معتبر حتی وقتی نتیجه کوتاه‌مدت نامطلوب است. پایبندی باید با شاخص‌های فرایندی مانند درصد معاملات مطابق برنامه سنجیده شود، نه فقط سود.','ممکن است معامله مطابق برنامه زیان‌ده باشد اما از نظر کیفیت اجرا صحیح ارزیابی شود.','تغییر استراتژی پس از چند معامله بدون نمونه کافی.','در ژورنال ده معامله، رعایت قوانین را مستقل از سود و زیان امتیازدهی کن.'),
(11,3,'مدیریت ضررهای متوالی','زیان‌های متوالی در هر سیستم احتمالی ممکن‌اند. باید قبل از معامله حد زیان روزانه یا هفتگی، شرایط توقف و بازبینی و کاهش حجم مشخص باشد. بازیابی زیان با افزایش بی‌قاعده ریسک، خطر نابودی حساب را زیاد می‌کند.','پنج زیان یک‌درصدی متوالی سرمایه را به حدود ۹۵٫۱٪ مقدار اولیه می‌رساند، نه دقیقاً ۹۵٪.','استفاده از مارتینگل بدون محاسبه سقف ریسک تجمعی.','اثر ده زیان متوالی با ریسک ثابت ۱٪ و ۳٪ را محاسبه و مقایسه کن.'),
(12,1,'ریسک تجمعی، افت سرمایه و هم‌بستگی معاملات','ریسک چند معامله هم‌زمان را نمی‌توان همیشه با جمع ساده درصدها یا با فرض استقلال محاسبه کرد. معاملات هم‌بسته ممکن است در یک رویداد هم‌زمان زیان دهند. افت سرمایه نسبت به اوج قبلی حساب سنجیده می‌شود.','دو موقعیت خرید روی دارایی‌های وابسته ممکن است در شوک دلار هم‌زمان تحت فشار قرار گیرند.','فرض تنوع‌بخشی صرفاً به دلیل متفاوت بودن نام نمادها.','برای موقعیت‌های باز، سناریوی شوک مشترک و مجموع زیان بالقوه را بنویس.'),
(12,2,'تنظیم حجم بر اساس نوسان','در تنظیم حجم مبتنی بر نوسان، فاصله حد ضرر یا اندازه موقعیت با شاخصی مانند ATR هماهنگ می‌شود تا ریسک پولی قابل کنترل بماند. ATR جهت بازار را پیش‌بینی نمی‌کند و تغییر ناگهانی نوسان می‌تواند مدل را بی‌اعتبار کند.','اگر فاصله حد ضرر از ۵ به ۱۰ واحد افزایش یابد، با ثابت بودن بودجه ریسک، حجم نظری تقریباً نصف می‌شود.','افزایش حجم صرفاً به دلیل پایین بودن نوسان بدون توجه به رویدادهای پیش رو.','حجم فرضی را برای سه مقدار ATR با بودجه ریسک ثابت محاسبه کن.'),
(12,3,'طراحی محدودیت‌های حفاظتی','محدودیت‌های حفاظتی شامل سقف ریسک هر معامله، سقف زیان روزانه، تعداد موقعیت، حد اسپرد، شرایط قطع اتصال و توقف پس از خطا هستند. این قواعد باید پیش از اجرای واقعی آزموده و ثبت شوند.','اگر داده قیمت قطع شود، سیستم نباید با فرض ثابت بودن بازار سفارش‌های جدید بی‌محابا ارسال کند.','اعتماد کامل به یک حد ضرر نرم‌افزاری بدون سناریوی خرابی اتصال.','یک جدول «رخداد، واکنش سیستم، مسئول بررسی» برای پنج خطای عملیاتی بساز.'),
(13,1,'معرفی چارچوب معاملاتی 10X','در این دوره، 10X به‌عنوان یک چارچوب اجرایی منظم بررسی می‌شود: تعریف شرایط بازار، انتخاب موقعیت، کنترل ریسک، اجرای معامله و ثبت نتیجه. جزئیات سیگنال‌ها و پارامترهای اختصاصی باید از سند رسمی و تأییدشده سیستم وارد شوند؛ این درس هیچ قانون ورود اختصاصی را ادعا نمی‌کند.','برای یک معامله نمونه، مسیر تصمیم را از مشاهده بازار تا ثبت نتیجه روی کاغذ ترسیم کن، بدون اینکه سیگنال ساختگی تعریف شود.','برداشت اینکه نام 10X به معنی تضمین ده‌برابر شدن سرمایه است.','اجزای لازم برای مستندسازی رسمی سیستم را فهرست کن: بازار، تایم‌فریم، سیگنال، خروج، ریسک و استثناها.'),
(13,2,'قوانین اصلی و پیش‌نیازهای سیستم','پیش از اجرای هر سیستم اختصاصی باید نسخه قوانین، نمادهای مجاز، ساعات کار، مشخصات قرارداد، حداقل سرمایه، شرایط توقف و روش آزمون مشخص باشد. تا زمانی که سند معتبر 10X تأیید نشده، نباید آستانه‌ها یا دستور معامله را حدس زد.','یک چک‌لیست آماده‌سازی شامل نسخه سیستم، اتصال کارگزار، داده قیمت و محدودیت ریسک تنظیم کن.','استفاده از قوانین شنیده‌شده یا نسخه قدیمی به‌جای دستورالعمل معتبر.','برای هر قانون اجرایی، منبع، نسخه و تاریخ تأیید تعیین کن.'),
(14,1,'آماده‌سازی نمودار و ابزارها','محیط اجرای منظم به ساعت درست سرور، نماد صحیح، تایم‌فریم، داده کافی، وضعیت اتصال و ابزار ثبت معامله نیاز دارد. تنظیمات باید قابل تکرار باشند و تغییر آن‌ها در ژورنال ثبت شود. ابزارهای خاص 10X تنها بر اساس مستندات رسمی پیکربندی می‌شوند.','پیش از جلسه آزمایشی، تفاوت ساعت سرور و منطقه زمانی خبرها را بررسی کن تا زمان‌بندی اشتباه نشود.','اجرای سیستم روی نمادی با پسوند یا مشخصات قرارداد متفاوت بدون کنترل.','یک برگه تنظیمات استاندارد برای محیط آزمایشی تهیه و از آن نسخه بگیر.'),
(14,2,'تشخیص موقعیت معاملاتی','تشخیص موقعیت یعنی بررسی شرایط لازم و ممنوع‌کننده پیش از تصمیم. در یک سیستم قانون‌محور، هر شرط باید پاسخ قابل مشاهده داشته باشد و نتیجه «عدم معامله» نیز خروجی معتبر است. معیارهای اختصاصی 10X باید از قواعد تأییدشده استخراج شوند.','اگر کیفیت داده یا اسپرد خارج از محدوده مجاز مستند باشد، موقعیت کنار گذاشته می‌شود حتی اگر نمودار جذاب به نظر برسد.','تفسیر شخصی قوانین برای توجیه ورود دلخواه.','فرم ثبت شرایط بازار، دلیل پذیرش یا رد موقعیت و تصویر نمودار طراحی کن.'),
(14,3,'اجرای ورود و مدیریت معامله','پس از تأیید موقعیت طبق قوانین رسمی، باید حجم، نوع سفارش، محل خروج، هزینه و سناریوی قطع اتصال کنترل شود. هر تغییر در معامله باید دلیل از پیش مجاز داشته باشد؛ دست‌کاری هیجانی حد ضرر ممنوع است.','در حساب آزمایشی، سفارش را با کنترل دوباره نماد، حجم و حدود ثبت و سپس اجرای واقعی آن را با قیمت درخواستی مقایسه کن.','فرض اینکه ارسال موفق سفارش به معنی اجرای دقیق با همان قیمت است.','چک‌لیست پیش از ارسال و پس از اجرا را برای پنج معامله آزمایشی تکمیل کن.'),
(15,1,'ثبت و تحلیل معاملات سیستم','ژورنال استاندارد باید زمان، نماد، نسخه قوانین، شرایط ورود، قیمت اجرا، حجم، هزینه، خروج، نتیجه و میزان رعایت برنامه را ثبت کند. تحلیل باید میان کیفیت سیگنال، کیفیت اجرا و شرایط بازار تفاوت بگذارد.','معامله‌ای با سیگنال معتبر ولی لغزش زیاد را جداگانه به‌عنوان مشکل اجرا علامت بزن، نه لزوماً شکست منطق استراتژی.','حذف معاملات زیان‌ده یا خلاف برنامه از گزارش عملکرد.','برای ۲۰ معامله، نرخ رعایت قواعد، میانگین R و بیشترین افت را گزارش کن.'),
(16,1,'طراحی برنامه تمرین','برنامه تمرین مؤثر هدف قابل سنجش، زمان‌بندی، محیط آزمایشی و معیار عبور به مرحله بعد دارد. تمرین باید از شناخت نمودار و قوانین شروع و به اجرای بدون کمک و تحلیل خطا برسد. سرعت پیشرفت نباید با سود کوتاه‌مدت سنجیده شود.','هفته اول فقط برچسب‌گذاری موقعیت‌ها، هفته دوم اجرای دمو و هفته سوم بازبینی ژورنال را برنامه‌ریزی کن.','رفتن به سرمایه واقعی قبل از رسیدن به ثبات اجرایی.','برای چهار هفته، هدف، تعداد تمرین و معیار قبولی تعیین کن.'),
(16,2,'تحلیل اشتباهات معاملاتی','خطاها را به دسته‌های تحلیل، اجرای سفارش، مدیریت ریسک، ثبت داده و روان‌شناسی تقسیم کن. هر خطا باید با شاهد، علت محتمل و اقدام اصلاحی مشخص ثبت شود؛ برچسب مبهم «بی‌دقتی» بهبود ایجاد نمی‌کند.','اگر حجم دو برابر مقدار مجاز ثبت شده، علت را در ورودی محاسبه، گام حجم یا کنترل نهایی جست‌وجو کن.','یکی دانستن نتیجه زیان‌ده با اجرای اشتباه.','پنج خطای اخیر را دسته‌بندی و برای هرکدام یک کنترل پیشگیرانه بنویس.'),
(16,3,'بهینه‌سازی فرآیند تصمیم‌گیری','بهینه‌سازی تصمیم‌گیری با کاهش ابهام قواعد، بهبود کیفیت داده، ثبت استثناها و ارزیابی مستقل تغییرات انجام می‌شود. هر اصلاح باید ابتدا در داده یا محیط جداگانه آزموده شود تا بیش‌برازش ایجاد نشود.','قبل از افزودن فیلتر خبری، عملکرد نسخه پایه و نسخه جدید را روی دوره زمانی یکسان و سپس خارج از نمونه مقایسه کن.','اعمال هم‌زمان چند تغییر و ناتوانی در تشخیص علت بهبود یا افت.','یک تغییر کوچک با فرضیه روشن، معیار موفقیت و روش آزمون مستقل تعریف کن.'),
]

def sha(b): return hashlib.sha256(b).hexdigest()
def stop(msg):
    print('R13_B3=BLOCKED'); print('REASON='+str(msg)); sys.exit(1)

def db(query):
    p=subprocess.run([MYSQL,'--batch','--raw','--skip-column-names','--default-character-set=utf8mb4',DB],input=query,text=True,capture_output=True,timeout=120)
    if p.returncode: stop('DATABASE_ERROR '+p.stderr[:250])
    return p.stdout.strip()

def esc(s): return "'"+s.replace('\\','\\\\').replace("'","''")+"'"

def body_for(entry):
    course,num,title,core,example,mistake,exercise=entry
    blocks=[
        {'type':'heading','text':'هدف یادگیری'},
        {'type':'paragraph','text':'پس از مطالعه این درس باید بتوانی مفهوم «'+title+'» را توضیح بدهی، یک نمونه عملی تحلیل کنی و خطاهای رایج آن را تشخیص دهی.'},
        {'type':'heading','text':'مفهوم و اصول کاربردی'},
        {'type':'paragraph','text':core},
        {'type':'heading','text':'مثال کاربردی'},
        {'type':'paragraph','text':example},
        {'type':'callout','title':'اشتباه رایج','text':mistake},
        {'type':'heading','text':'تمرین عملی'},
        {'type':'paragraph','text':exercise},
        {'type':'bullets','items':['تعریف مفهوم را با کلمات خودت بنویس.','مثال درس را با فرض‌های مشخص بررسی کن.','شرایطی را که تحلیل یا تصمیم نامعتبر می‌شود ثبت کن.']},
        {'type':'summary','text':'در این درس «'+title+'» را از نظر مفهوم، کاربرد و محدودیت بررسی کردی. نتیجه تمرین را ثبت کن و پیش از تصمیم واقعی، ریسک و فرض‌های تحلیل را مستقل ارزیابی کن.'},
    ]
    if (course,num) in [(1,2),(2,2),(4,1),(10,2),(12,2)]:
        blocks.insert(6,{'type':'chart','title':'نمایش آموزشی فرضی؛ داده واقعی نیست','items':[{'label':'سناریو الف','value':70},{'label':'سناریو ب','value':45},{'label':'سناریو ج','value':25}]})
    if (course,num) in [(1,3),(4,1),(11,1)]:
        blocks.insert(7,{'type':'balance-simulator','title':'شبیه‌ساز مفهومی فشار نسبی خرید و فروش؛ مستقل از موضوع اصلی تمرین'})
    return json.dumps({'version':'10x.lesson.v1','blocks':blocks},ensure_ascii=False,separators=(',',':'))

if __name__=='__main__':
    MYSQL=shutil.which('mariadb') or shutil.which('mysql')
    if not MYSQL: stop('MYSQL_CLIENT_MISSING')
    if len(DATA)!=49: stop('EXPECTED_49_CONTENT_RECORDS_GOT_'+str(len(DATA)))
    keys=[(a,b) for a,b,*_ in DATA]
    if len(set(keys))!=49 or (1,1) in keys: stop('DUPLICATE_OR_FIRST_LESSON_INCLUDED')
    distribution=[3,3,3,3,4,4,4,4,3,4,3,3,2,3,1,3]
    expected={(i,j) for i,n in enumerate(distribution,1) for j in range(1,n+1)}-{(1,1)}
    if set(keys)!=expected: stop('LESSON_ID_SET_MISMATCH')
    payload={f'{LESSON_PREFIX}{c:02d}_{n:02d}':(title,body_for(e)) for e in DATA for c,n,title,*_ in [e]}
    if any(len(body)>20000 for _,body in payload.values()): stop('BODY_LIMIT_EXCEEDED')
    if not (ROOT/'public/miniapp/tenx-lesson-renderer.js').is_file(): stop('RENDERER_NOT_INSTALLED')
    renderer=(ROOT/'public/miniapp/tenx-lesson-renderer.js').read_text()
    if "10x.lesson.v1" not in renderer: stop('RENDERER_VERSION_MISMATCH')
    if 'tenx-lesson-renderer.js?v=r13b1' not in (ROOT/'public/miniapp/index.html').read_text(): stop('RENDERER_NOT_LINKED')
    print('PREFLIGHT_CONTENT=PASS_49',flush=True)
    # Validate current DB rows and title matching; JSON_OBJECT produces a single JSON record per row.
    raw=db("SELECT JSON_OBJECT('id',id,'title',title,'courseId',courseId,'status',status,'summary',summary,'body',body,'videoUrl',videoUrl) FROM Lesson WHERE id LIKE 'tenx_q09_lesson_%' ORDER BY id;")
    try: records=[json.loads(x) for x in raw.splitlines()]
    except Exception as e: stop('SNAPSHOT_PARSE_ERROR '+str(e))
    current={r['id']:r for r in records}
    if len(current)!=50 or len(records)!=50: stop('DATABASE_LESSON_COUNT_NOT_50')
    if FIRST not in current or not current[FIRST]['body']: stop('FIRST_LESSON_MISSING_OR_EMPTY')
    for lid,(title,body) in payload.items():
        r=current.get(lid)
        if not r: stop('LESSON_MISSING '+lid)
        if r['title']!=title: stop('TITLE_MISMATCH '+lid)
        if r['courseId']!='tenx_q09_course_'+lid[-5:-3]: stop('COURSE_ID_MISMATCH '+lid)
        if r['status']!='PUBLISHED': stop('NOT_PUBLISHED '+lid)
        if r['body'] not in (None,''): stop('EXISTING_CONTENT_BLOCKED '+lid)
    print('PREFLIGHT_DATABASE=PASS_50_AND_EMPTY_49',flush=True)
    OUT=BASE/('r13-b3-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f')); OUT.mkdir(mode=0o700)
    snapshot=OUT/'before.json'; snapshot.write_text(json.dumps(records,ensure_ascii=False,indent=2)); snapshot.chmod(0o600)
    datafile=OUT/'content.json'; datafile.write_text(json.dumps({lid:{'summary':title+' — آموزش مفهومی، مثال کاربردی، خطاهای رایج و تمرین عملی.','body':body} for lid,(title,body) in payload.items()},ensure_ascii=False,indent=2)); datafile.chmod(0o600)
    # Rollback is guarded against later edits: each row must still match the published body hash.
    rollback=['START TRANSACTION;']
    for lid,(title,body) in sorted(payload.items()):
        r=current[lid]
        nullable=lambda x:'NULL' if x is None else esc(str(x))
        rollback.append('UPDATE Lesson SET summary='+nullable(r['summary'])+',body='+nullable(r['body'])+' WHERE id='+esc(lid)+' AND SHA2(body,256)='+esc(sha(body.encode()))+';')
    rollback.append('COMMIT;')
    (OUT/'rollback_guarded.sql').write_text('\n'.join(rollback)+'\n')
    (OUT/'rollback_guarded.sql').chmod(0o600)
    # Atomic transaction: a NOT NULL guard forces failure before COMMIT if any row was skipped.
    # A failed mysql client closes its connection, rolling back uncommitted InnoDB changes.
    sql=['CREATE TEMPORARY TABLE tenx_r13b3_counts (n INT NOT NULL);',
         'CREATE TEMPORARY TABLE tenx_r13b3_guard (n INT NOT NULL);',
         'START TRANSACTION;']
    for lid,(title,body) in sorted(payload.items()):
        summary=title+' — آموزش مفهومی، مثال کاربردی، خطاهای رایج و تمرین عملی.'
        sql.append('UPDATE Lesson SET summary='+esc(summary)+',body='+esc(body)+' WHERE id='+esc(lid)+" AND status='PUBLISHED' AND (body IS NULL OR body='') AND title="+esc(title)+';')
        sql.append('INSERT INTO tenx_r13b3_counts VALUES (ROW_COUNT());')
    sql.extend(['INSERT INTO tenx_r13b3_guard SELECT IF(SUM(n)=49,49,NULL) FROM tenx_r13b3_counts;',
                'COMMIT;', 'SELECT n FROM tenx_r13b3_guard;'])
    patch=OUT/'publish.sql'; patch.write_text('\n'.join(sql)+'\n'); patch.chmod(0o600)
    print('BACKUP=PASS '+str(snapshot),flush=True)
    # Use mysql client input via file: delimiter directives are client-side, not SQL.
    proc=subprocess.run([MYSQL,'--batch','--skip-column-names','--default-character-set=utf8mb4',DB],input=patch.read_text(),text=True,capture_output=True,timeout=120)
    if proc.returncode: stop('TRANSACTION_FAILED '+proc.stderr[-500:])
    if proc.stdout.strip().splitlines()[-1:]!=['49']: stop('TRANSACTION_OUTPUT_UNEXPECTED '+proc.stdout[-200:])
    # Verify all 49 hashes in one SELECT; never print bodies.
    hashes=db("SELECT id,SHA2(body,256) FROM Lesson WHERE id LIKE 'tenx_q09_lesson_%' ORDER BY id;")
    got={parts[0]:parts[1] for line in hashes.splitlines() if len(parts:=line.split('\t'))==2}
    bad=[lid for lid,(_,body) in payload.items() if got.get(lid,'').lower()!=sha(body.encode()).lower()]
    if bad: stop('POSTVERIFY_HASH_MISMATCH '+','.join(bad))
    if got.get(FIRST,'').lower()!=sha(current[FIRST]['body'].encode()).lower(): stop('FIRST_LESSON_CHANGED')
    print('TRANSACTION=COMMITTED_49')
    print('POSTVERIFY=PASS_49_HASHES')
    print('FIRST_LESSON=UNCHANGED')
    print('COURSES=16')
    print('TOTAL_LESSONS_WITH_CONTENT=50')
    print('DATABASE_CHANGED=49_LESSON_SUMMARY_AND_BODY_ONLY')
    print('SERVICES_RESTARTED=NO')
    print('BACKUP_PATH='+str(snapshot))
    print('ROLLBACK_PATH='+str(OUT/'rollback_guarded.sql'))
    print('R13_B3=PASS_PUBLISHED_49')
